import data from './icons-data.json';
import { sanitizeSvgMarkup } from './html-import.ts';
import type { NewNode } from './doc.ts';

/**
 * The Lucide icon set (ISC) as data. Generated by scripts/gen-icons.ts. Its own entry point, so that
 * the editor loads these 400 KB only when the picker opens.
 */
const ICONS: Record<string, string> = (data as { icons: Record<string, string> }).icons;

/** Words people search for that are not in an icon's name. */
const SYNONYMS: Record<string, string[]> = {
  add: ['plus'], remove: ['minus', 'trash', 'x'], delete: ['trash', 'x'], close: ['x'], cancel: ['x', 'ban'], settings: ['settings', 'cog', 'sliders'], gear: ['settings', 'cog'], preferences: ['settings', 'sliders'],
  menu: ['menu', 'ellipsis'], hamburger: ['menu'], more: ['ellipsis'], back: ['arrow-left', 'chevron-left'], next: ['arrow-right', 'chevron-right'], forward: ['arrow-right'], profile: ['user', 'circle-user'], person: ['user'], account: ['user'], people: ['users'], team: ['users'],
  email: ['mail'], message: ['message', 'mail'], chat: ['message'], notification: ['bell'], alert: ['triangle-alert', 'bell', 'circle-alert'], warning: ['triangle-alert'], error: ['circle-x', 'circle-alert'], info: ['info'], help: ['circle-question-mark'], question: ['circle-question-mark'],
  success: ['check', 'circle-check'], done: ['check'], ok: ['check'], tick: ['check'], favourite: ['star', 'heart'], favorite: ['star', 'heart'], like: ['heart', 'thumbs-up'], love: ['heart'], save: ['save', 'bookmark'], download: ['download'], upload: ['upload'], share: ['share'], link: ['link'], external: ['external-link'],
  edit: ['pencil', 'square-pen'], write: ['pencil'], copy: ['copy'], duplicate: ['copy'], paste: ['clipboard'], cart: ['shopping-cart'], basket: ['shopping-basket'], shop: ['store', 'shopping-bag'], price: ['tag', 'dollar-sign'], money: ['banknote', 'dollar-sign', 'coins'], payment: ['credit-card'], card: ['credit-card'],
  picture: ['image'], photo: ['image', 'camera'], video: ['video', 'film'], sound: ['volume'], audio: ['volume', 'music'], play: ['play'], pause: ['pause'], stop: ['square'], location: ['map-pin'], place: ['map-pin'], time: ['clock'], date: ['calendar'], schedule: ['calendar'],
  find: ['search'], magnifier: ['search'], filter: ['funnel', 'list-filter'], sort: ['arrow-up-down'], home: ['house'], house: ['house'], world: ['globe'], web: ['globe'], internet: ['globe'], dark: ['moon'], light: ['sun'], theme: ['sun', 'moon', 'palette'], security: ['shield', 'lock'], password: ['lock', 'key'], login: ['log-in'], logout: ['log-out'],
  chart: ['chart'], graph: ['chart'], stats: ['chart'], analytics: ['chart'], database: ['database'], file: ['file'], document: ['file-text'], folder: ['folder'], code: ['code'], terminal: ['terminal'], bug: ['bug'], ai: ['sparkles', 'bot'], magic: ['sparkles', 'wand'],
};

export function iconNames(): string[] {
  return Object.keys(ICONS);
}

export function hasIcon(name: string): boolean {
  return Object.hasOwn(ICONS, name);
}

/** Icons by name and common words, best first. */
export function searchIcons(query: string, limit = 60): string[] {
  const words = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const names = iconNames();
  if (!words.length) return names.slice(0, limit);
  const scored: { name: string; score: number }[] = [];
  for (const name of names) {
    let score = 0;
    for (const word of words) {
      let best = 0;
      if (name === word) best = 100;
      else if (name.startsWith(`${word}-`) || name.endsWith(`-${word}`)) best = 60;
      else if (name.split('-').includes(word)) best = 50;
      else if (name.startsWith(word)) best = 40;
      else if (name.includes(word)) best = 20;
      for (const alias of SYNONYMS[word] ?? []) {
        if (name === alias) best = Math.max(best, 90);
        else if (name.startsWith(`${alias}-`) || name.endsWith(`-${alias}`)) best = Math.max(best, 45);
        else if (name.includes(alias)) best = Math.max(best, 15);
      }
      if (!best) {
        score = 0;
        break;
      }
      score += best;
    }
    if (score) scored.push({ name, score: score - name.length / 100 });
  }
  return scored.sort((a, b) => b.score - a.score).slice(0, limit).map((s) => s.name);
}

function distance(a: string, b: string): number {
  let row = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const next = [i];
    for (let j = 1; j <= b.length; j++) next[j] = Math.min(next[j - 1]! + 1, row[j]! + 1, row[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1));
    row = next;
  }
  return row[b.length]!;
}

/** For a name that is almost right. */
export function closestIcons(name: string, limit = 6): string[] {
  const direct = searchIcons(name, limit);
  if (direct.length) return direct;
  return iconNames().map((n) => ({ n, d: distance(name, n) })).sort((a, b) => a.d - b.d).slice(0, limit).map((x) => x.n);
}

export interface IconOptions { strokeWidth?: number; color?: string }

/** One icon as editable SVG. It draws in `currentColor` unless given a colour. */
export function iconSvg(name: string, options: IconOptions = {}): string {
  const inner = hasIcon(name) ? ICONS[name]! : '';
  const stroke = options.color && /^[#\w(),.\s%-]+$/.test(options.color) ? options.color : 'currentColor';
  const width = Number.isFinite(options.strokeWidth) && options.strokeWidth! > 0 ? options.strokeWidth : 2;
  return sanitizeSvgMarkup(`<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="${stroke}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`);
}

/** One icon as a layer spec. Throws for a name that is not in the set. */
export function iconSpec(name: string, options: IconOptions & { size?: number } = {}): NewNode {
  if (!hasIcon(name)) throw new Error(`There is no icon "${name}". Call icon_search.`);
  const size = options.size ?? 24;
  return { type: 'svg', tag: 'svg', name, svg: iconSvg(name, options), style: { width: `${size}px`, height: `${size}px`, flexShrink: '0' } };
}
